// Retrieve version string and validate basic invariants about the returned pointer.
const char *ver = swoole_version();
FUZZ_ASSERT(ver != nullptr, "swoole_version returned null");
FUZZ_ASSERT(ver[0] != '\0', "swoole_version returned empty string");
// Caller must not modify or free the returned pointer; no further action.

// Retrieve numeric version identifier and validate it is non-negative.
int vid = swoole_version_id();
FUZZ_ASSERT(vid >= 0, "swoole_version_id returned a negative value");

// Retrieve API version identifier and validate it is non-negative.
int aid = swoole_api_version_id();
FUZZ_ASSERT(aid >= 0, "swoole_api_version_id returned a negative value");
